#[test]
fn block_refusals_match_the_per_query_loop() {
    let (nh, nkv, hd) = (4usize, 2usize, 64usize);
    let group = nh / nkv;
    let kv = filled(nh, nkv, hd, 32, 20, 2, 5);
    let q_stride = group * hd;
    let q = vec![1i64 << 32; 8 * q_stride];
    let mut out = vec![0i64; 8 * group * hd];
    assert_eq!(
        kv.attn_block_f32(1, 0, &q, q_stride, 0..1, &mut out[..group * hd]),
        Err(AttnError::LayerOutOfRange {
            layer: 1,
            n_layer: 1
        })
    );
    assert_eq!(
        kv.attn_block_f32(0, nkv, &q, q_stride, 0..1, &mut out[..group * hd]),
        Err(AttnError::HeadOutOfRange {
            head: nkv,
            n_head: nkv
        })
    );
    assert_eq!(
        kv.attn_block_f32(0, 0, &q, q_stride - 1, 0..1, &mut out[..group * hd]),
        Err(AttnError::BadGeometry)
    );
    assert_eq!(
        kv.attn_block_f32(
            0,
            0,
            &q[..q_stride + group * hd - 1],
            q_stride,
            0..2,
            &mut out[..2 * group * hd]
        ),
        Err(AttnError::RowLength {
            expected: q_stride + group * hd,
            got: q_stride + group * hd - 1
        })
    );
    assert_eq!(
        kv.attn_block_f32(0, 0, &q, q_stride, 0..2, &mut out[..group * hd]),
        Err(AttnError::RowLength {
            expected: 2 * group * hd,
            got: group * hd
        })
    );
    assert_eq!(
        kv.attn_block_f32(0, 0, &q, q_stride, 5..5, &mut out[..0]),
        Ok(())
    );
    // Positions 18, 19 are occupied; 20 and 21 are not. The two valid queries are computed
    // (and written) before the refusal, as in the loop.
    let mut got = vec![0i64; 4 * group * hd];
    let mut want = vec![0i64; 4 * group * hd];
    let r = kv.attn_block_f32(0, 1, &q, q_stride, 18..22, &mut got);
    let e = reference(&kv, 1, &q, q_stride, 18..22, &mut want);
    assert_eq!(r, Err(AttnError::PositionOutOfRange { pos: 20, len: 20 }));
    assert_eq!(r, e);
    assert_eq!(got, want);
    assert!(got[..2 * group * hd].iter().any(|&w| w != 0));
    assert_eq!(
        kv.attn_block_f32(0, 0, &q, q_stride, 20..21, &mut out[..group * hd]),
        Err(AttnError::PositionOutOfRange { pos: 20, len: 20 })
    );
    let q32 = KvState::with_carrier(1, nh, nkv, hd, 4, Carrier::Q32).expect("geometry");
    let mut q32 = q32;
    q32.append(0, &vec![0; nkv * hd], &vec![0; nkv * hd])
        .unwrap();
    assert_eq!(
        q32.attn_block_f32(0, 0, &q, q_stride, 0..1, &mut out[..group * hd]),
        Err(AttnError::BadGeometry)
    );

